const wFWorkflowTagList = `-- name: WFWorkflowTagList :many
SELECT "partition", account_id, region, name, item_key, item_value FROM glue_workflow_tag WHERE partition = ?1 AND account_id = ?2 AND region = ?3 AND name = ?4 ORDER BY partition, account_id, region, name, item_key
`

type WFWorkflowTagListParams struct {
	Partition string
	AccountID string
	Region    string
	Name      string
}

func (q *Queries) WFWorkflowTagList(ctx context.Context, arg WFWorkflowTagListParams) ([]GlueWorkflowTag, error) {
	rows, err := q.db.QueryContext(ctx, wFWorkflowTagList,
		arg.Partition,
		arg.AccountID,
		arg.Region,
		arg.Name,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GlueWorkflowTag{}
	for rows.Next() {
		var i GlueWorkflowTag
		if err := rows.Scan(
			&i.Partition,
			&i.AccountID,
			&i.Region,
			&i.Name,
			&i.ItemKey,
			&i.ItemValue,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

